<?php require_once __DIR__.'/../includes/bootstrap.php'; if(current_user()) redirect('/dashboard.php'); $pageTitle='Log in — LinkForge';
if(request_is_post()){verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');if(login_limited($email)){flash('error','Too many attempts. Try again in 15 minutes.');}else{$s=db()->prepare('SELECT id,email,password_hash FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($password,$u['password_hash'])){db()->prepare('DELETE FROM login_attempts WHERE email=?')->execute([$email]);login_user($u);redirect('/dashboard.php');}record_login_attempt($email);flash('error','Invalid email or password.');}} require __DIR__.'/../includes/header.php'; ?><main class="auth-page"><form class="auth-card" method="post"><p class="eyebrow">WELCOME BACK</p><h1>Continue with purpose.</h1><?=csrf_field()?><label>Email <input name="email" type="email" autocomplete="email" required value="<?=e($_POST['email']??'')?>"></label><label>Password <input name="password" type="password" autocomplete="current-password" required></label><button class="button wide">Log in</button><p>New to LinkForge? <a href="<?=e(base_url())?>/register.php">Create an account</a></p></form></main><?php require __DIR__.'/../includes/footer.php'; ?>
